import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { toast } from '../libs/toast';
import { FaPlus, FaEdit, FaTrash, FaSearch, FaCalendarAlt, FaClock } from 'react-icons/fa';
import axios from 'axios';
import './Programs.css';
import { toPersianDigits } from '../utils/locale';

const Programs: React.FC = () => {
  const [programs, setPrograms] = useState([]);
  const [filteredPrograms, setFilteredPrograms] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchPrograms();
  }, []);

  useEffect(() => {
    filterPrograms();
  }, [programs, searchTerm]);

  const fetchPrograms = async () => {
    try {
      const response = await axios.get('/api/programs');
      setPrograms(response.data);
    } catch (error) {
      toast.error('خطا در دریافت لیست برنامه‌ها');
    } finally {
      setLoading(false);
    }
  };

  const filterPrograms = () => {
    let filtered = programs;

    if (searchTerm) {
      filtered = filtered.filter((program: any) =>
        (program.title || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
        (program.description || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
        (program.program_type || '').toLowerCase().includes(searchTerm.toLowerCase())
      );
    }

    setFilteredPrograms(filtered);
  };

  const handleDelete = async (id: string) => {
    if (window.confirm('آیا از حذف این برنامه مطمئن هستید؟')) {
      try {
        await axios.delete(`/api/programs/${id}`);
        toast.success('برنامه با موفقیت حذف شد');
        fetchPrograms();
      } catch (error) {
        toast.error('خطا در حذف برنامه');
      }
    }
  };

  const getProgramTypeColor = (type: string) => {
    const colors = {
      'theater': '#e74c3c',
      'music': '#9b59b6',
      'dance': '#f39c12',
      'concert': '#27ae60',
      'workshop': '#3498db',
      'exhibition': '#e67e22',
      'conference': '#1abc9c',
      'other': '#95a5a6'
    };
    return colors[type as keyof typeof colors] || colors.other;
  };

  const getProgramTypeLabel = (type: string) => {
    const labels = {
      'theater': 'تئاتر',
      'music': 'موسیقی',
      'dance': 'رقص',
      'concert': 'کنسرت',
      'workshop': 'کارگاه',
      'exhibition': 'نمایشگاه',
      'conference': 'کنفرانس',
      'other': 'سایر'
    };
    return labels[type as keyof typeof labels] || labels.other;
  };

  if (loading) {
    return (
      <div className="loading-container">
        <div className="loading-spinner"></div>
        <p>در حال بارگذاری...</p>
      </div>
    );
  }

  return (
    <div className="programs-container">
      <div className="page-header">
        <h1>مدیریت برنامه‌ها</h1>
        <Link to="/programs/new" className="btn btn-success">
          <FaPlus />
          برنامه جدید
        </Link>
      </div>

      <div className="filters-section">
        <div className="search-box">
          <FaSearch />
          <input
            type="text"
            placeholder="جستجو در نام، توضیحات یا نوع برنامه..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
        </div>
      </div>

      <div className="programs-grid">
        {filteredPrograms.length === 0 ? (
          <div className="empty-state">
            <FaCalendarAlt />
            <p>هیچ برنامه‌ای یافت نشد</p>
            <Link to="/programs/new" className="btn btn-success">
              ایجاد اولین برنامه
            </Link>
          </div>
        ) : (
          filteredPrograms.map((program: any) => (
            <div key={program.id} className="program-card">
              <div className="card-header">
                <div className="program-info">
                  <div
                    className="program-type-badge"
                    style={{ backgroundColor: getProgramTypeColor(program.program_type) }}
                  >
                    {getProgramTypeLabel(program.program_type)}
                  </div>
                  <h3>{program.title}</h3>
                </div>
                <div className="card-actions">
                  <Link
                    to={`/programs/${program.id}/edit`}
                    className="action-btn edit"
                    title="ویرایش"
                  >
                    <FaEdit />
                  </Link>
                  <button
                    onClick={() => handleDelete(program.id)}
                    className="action-btn delete"
                    title="حذف"
                  >
                    <FaTrash />
                  </button>
                </div>
              </div>

              <div className="card-content">
                {program.description && (
                  <div className="info-item">
                    <span className="label">توضیحات:</span>
                    <span className="value">{program.description}</span>
                  </div>
                )}
                {program.duration && (
                  <div className="info-item">
                    <span className="label">مدت زمان:</span>
                    <span className="value duration">
                      <FaClock />
                      {toPersianDigits(program.duration)} دقیقه
                    </span>
                  </div>
                )}
                {program.capacity && (
                  <div className="info-item">
                    <span className="label">ظرفیت:</span>
                    <span className="value">{toPersianDigits(program.capacity)} نفر</span>
                  </div>
                )}
                {program.price && (
                  <div className="info-item">
                    <span className="label">قیمت:</span>
                    <span className="value price">{toPersianDigits(program.price.toLocaleString())} تومان</span>
                  </div>
                )}
              </div>

              <div className="card-footer">
                <div className="created-info">
                  ایجاد شده در: {new Date(program.created_at).toLocaleDateString('fa-IR')}
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default Programs;
