import React from 'react';
import { BrowserRouter as Router, Routes, Route } from 'react-router-dom';
import { ToastContainer } from './libs/toast';

// Context
import { AuthProvider } from './contexts/AuthContext';

// Components
import Layout from './components/Layout/Layout';
import ProtectedRoute from './components/Auth/ProtectedRoute';

// Pages
import Home from './pages/Home';
import Dashboard from './pages/Dashboard';
import Login from './pages/Login';
import Announcements from './pages/Announcements';
import CreateAnnouncement from './pages/CreateAnnouncement';
import AnnouncementDetail from './pages/AnnouncementDetail';
import Actors from './pages/Actors';
import Programs from './pages/Programs';
import CreateActor from './pages/CreateActor';
import CreateProgram from './pages/CreateProgram';
import DisplayPage from './pages/DisplayPage';
import PosterView from './pages/PosterView';
import Roles from './pages/Roles';
import Estimates from './pages/Estimates';
import CreateEstimate from './pages/CreateEstimate';
import EstimateDetail from './pages/EstimateDetail';
import BulkUpload from './pages/BulkUpload';

// Styles
import './App.css';

function App() {
  return (
    <AuthProvider>
      <Router>
        <div className="App">
          <Routes>
            {/* Public Routes */}
            <Route path="/login" element={<Login />} />
            <Route path="/display" element={<DisplayPage />} />
            <Route path="/poster/:id" element={<PosterView />} />

            {/* Main Layout Routes */}
            <Route path="/" element={<Layout />}>
              <Route index element={<Home />} />

              {/* Protected Admin Routes */}
              <Route path="/dashboard" element={
                <ProtectedRoute>
                  <Dashboard />
                </ProtectedRoute>
              } />

              <Route path="/announcements" element={
                <ProtectedRoute>
                  <Announcements />
                </ProtectedRoute>
              } />

              <Route path="/announcements/create" element={
                <ProtectedRoute>
                  <CreateAnnouncement />
                </ProtectedRoute>
              } />
              <Route path="/announcements/new" element={
                <ProtectedRoute>
                  <CreateAnnouncement />
                </ProtectedRoute>
              } />
              <Route path="/announcements/:id" element={
                <ProtectedRoute>
                  <AnnouncementDetail />
                </ProtectedRoute>
              } />

              <Route path="/announcements/edit/:id" element={
                <ProtectedRoute>
                  <CreateAnnouncement />
                </ProtectedRoute>
              } />
              <Route path="/announcements/:id/edit" element={
                <ProtectedRoute>
                  <CreateAnnouncement />
                </ProtectedRoute>
              } />

              <Route path="/actors" element={
                <ProtectedRoute>
                  <Actors />
                </ProtectedRoute>
              } />
              <Route path="/actors/new" element={
                <ProtectedRoute>
                  <CreateActor />
                </ProtectedRoute>
              } />

              <Route path="/programs" element={
                <ProtectedRoute>
                  <Programs />
                </ProtectedRoute>
              } />
              <Route path="/programs/new" element={
                <ProtectedRoute>
                  <CreateProgram />
                </ProtectedRoute>
              } />

              <Route path="/roles" element={
                <ProtectedRoute>
                  <Roles />
                </ProtectedRoute>
              } />

              <Route path="/bulk-upload" element={
                <ProtectedRoute>
                  <BulkUpload />
                </ProtectedRoute>
              } />

              <Route path="/estimates" element={
                <ProtectedRoute>
                  <Estimates />
                </ProtectedRoute>
              } />
              <Route path="/estimates/new" element={
                <ProtectedRoute>
                  <CreateEstimate />
                </ProtectedRoute>
              } />
              <Route path="/estimates/:id" element={
                <ProtectedRoute>
                  <EstimateDetail />
                </ProtectedRoute>
              } />
            </Route>
          </Routes>

          <ToastContainer
            position="top-left"
            autoClose={5000}
            hideProgressBar={false}
            newestOnTop={false}
            closeOnClick
            rtl={true}
            pauseOnFocusLoss
            draggable
            pauseOnHover
            theme="light"
          />
        </div>
      </Router>
    </AuthProvider>
  );
}

export default App;
