import React, { useEffect, useState } from 'react';
import { useParams, useNavigate, Link } from 'react-router-dom';
import axios from 'axios';
import { toast } from '../libs/toast';
import DateObject from 'react-date-object';
import persian from 'react-date-object/calendars/persian';
import { toPersianDigits } from '../utils/locale';
import { FaCalendarAlt, FaClock, FaMapMarkerAlt, FaEdit, FaTrash } from 'react-icons/fa';

const AnnouncementDetail: React.FC = () => {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const [announcement, setAnnouncement] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const res = await axios.get(`/api/announcements/${id}`);
        setAnnouncement(res.data);
      } catch (err) {
    toast.error('خطا در دریافت آفیش');
        navigate('/announcements');
      } finally {
        setLoading(false);
      }
    };
    fetchData();
  }, [id, navigate]);

  const handleDelete = async () => {
    if (!id) return;
  if (!window.confirm('آیا از حذف این آفیش مطمئن هستید؟')) return;
    try {
      const token = localStorage.getItem('token');
      await axios.delete(`/api/announcements/${id}`, {
        headers: token ? { Authorization: `Bearer ${token}` } : undefined,
      });
    toast.success('آفیش با موفقیت حذف شد');
      navigate('/announcements');
    } catch (err) {
    toast.error('حذف آفیش با خطا مواجه شد');
    }
  };

  const formatDateFa = (dateStr: string) => {
    try {
      const obj = new DateObject({ date: new Date(dateStr) });
      return obj.convert(persian).format('YYYY/MM/DD');
    } catch { return dateStr; }
  };

  if (loading) {
    return <div className="loading-container"><div className="loading-spinner"></div><p>در حال بارگذاری...</p></div>;
  }

  if (!announcement) {
  return <div className="container p-4">آفیش یافت نشد</div>;
  }

  return (
    <div className="container p-4">
      <div className="card">
        <div className="card-body">
          <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
            <h1 style={{ margin: 0 }}>{announcement.title}</h1>
            <div style={{ display: 'flex', gap: '8px' }}>
              <Link to={`/announcements/${id}/edit`} className="btn btn-outline">
                <FaEdit /> ویرایش
              </Link>
              <button className="btn btn-danger" onClick={handleDelete}>
                <FaTrash /> حذف
              </button>
            </div>
          </div>

          {announcement.description && (
            <p style={{ marginTop: '12px' }}>{announcement.description}</p>
          )}

          <div className="announcement-details" style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: '10px', marginTop: '12px' }}>
            <div className="detail-item"><FaCalendarAlt /> <span>{formatDateFa(announcement.date)}</span></div>
            <div className="detail-item"><FaClock /> <span>{toPersianDigits(announcement.time)}</span></div>
            <div className="detail-item"><FaMapMarkerAlt /> <span>{announcement.venue}</span></div>
          </div>

          <div style={{ marginTop: '16px' }}>
            <h3>برنامه</h3>
            <p>{announcement.program_title || 'بدون برنامه'}</p>
            {announcement.program_description && <p>{announcement.program_description}</p>}
          </div>

          {announcement.actors && announcement.actors.length > 0 && (
            <div style={{ marginTop: '16px' }}>
              <h3>عوامل</h3>
              <ul>
                {announcement.actors.map((actor: any) => (
                  <li key={actor.id}>{actor.name}{actor.role_in_program ? ` - ${actor.role_in_program}` : ''}</li>
                ))}
              </ul>
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default AnnouncementDetail;
