import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useAuth } from '../../contexts/AuthContext';
import { FaBars, FaTimes, FaUser, FaSignOutAlt } from 'react-icons/fa';
import './Header.css';
import Logo, { ThemeToggle } from '../Logo';

const Header: React.FC = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const { admin, logout } = useAuth();
  const navigate = useNavigate();

  const handleLogout = () => {
    logout();
    navigate('/login');
  };

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
  };

  return (
    <header className="header">
      <div className="header-container">
        <div className="header-logo">
          <Link to="/">
            <Logo src="/logo.png.jpg" height={108} width={108} className="logo-image" alt="لوگو" />
            <span className="logo-text">سامانه رسا</span>
          </Link>
        </div>

        <nav className={`header-nav ${isMenuOpen ? 'active' : ''}`}>
          <ul className="nav-list">
            <li className="nav-item">
              <Link to="/" className="nav-link" onClick={() => setIsMenuOpen(false)}>
                صفحه اصلی
              </Link>
            </li>
            <li className="nav-item">
              <Link to="/display" className="nav-link" onClick={() => setIsMenuOpen(false)}>
                نمایش برنامه‌ها
              </Link>
            </li>
            {admin && (
              <>
                <li className="nav-item">
                  <Link to="/dashboard" className="nav-link" onClick={() => setIsMenuOpen(false)}>
                    داشبورد
                  </Link>
                </li>
                <li className="nav-item">
                  <Link to="/announcements" className="nav-link" onClick={() => setIsMenuOpen(false)}>
                    آفیش‌ها
                  </Link>
                </li>
                <li className="nav-item">
                  <Link to="/actors" className="nav-link" onClick={() => setIsMenuOpen(false)}>
                    عوامل
                  </Link>
                </li>
                <li className="nav-item">
                  <Link to="/programs" className="nav-link" onClick={() => setIsMenuOpen(false)}>
                    برنامه‌ها
                  </Link>
                </li>
                <li className="nav-item">
                  <Link to="/roles" className="nav-link" onClick={() => setIsMenuOpen(false)}>
                    نقش‌ها
                  </Link>
                </li>
                <li className="nav-item">
                  <Link to="/bulk-upload" className="nav-link" onClick={() => setIsMenuOpen(false)}>
                    آپلود اکسل
                  </Link>
                </li>
                <li className="nav-item">
                  <Link to="/estimates" className="nav-link" onClick={() => setIsMenuOpen(false)}>
                    برآوردها
                  </Link>
                </li>
              </>
            )}
          </ul>
        </nav>

        <div className="header-actions">
          <ThemeToggle />
          {admin ? (
            <div className="user-menu">
              <div className="user-info">
                <FaUser className="user-icon" />
                <span className="user-name">{admin.fullName}</span>
              </div>
              <button className="logout-btn" onClick={handleLogout}>
                <FaSignOutAlt />
                <span>خروج</span>
              </button>
            </div>
          ) : (
            <Link to="/login" className="login-btn">
              ورود
            </Link>
          )}
        </div>

        <button className="menu-toggle" onClick={toggleMenu}>
          {isMenuOpen ? <FaTimes /> : <FaBars />}
        </button>
      </div>
    </header>
  );
};

export default Header;