import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from '../libs/toast';
import axios from 'axios';

const CreateActor: React.FC = () => {
  const navigate = useNavigate();
  const [formData, setFormData] = useState({
    name: '',
    role: '',
    bio: '',
    phone: '',
    email: '',
  });
  const [loading, setLoading] = useState(false);

  const handleChange = (e: React.ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    setFormData(prev => ({ ...prev, [name]: value }));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!formData.name || !formData.role) {
      toast.error('نام و نقش الزامی است');
      return;
    }
    try {
      setLoading(true);
      const token = localStorage.getItem('token');
      await axios.post('/api/actors', formData, {
        headers: token ? { Authorization: `Bearer ${token}` } : undefined,
      });
      toast.success('عامل با موفقیت ایجاد شد');
      navigate('/actors');
    } catch (error) {
      toast.error('ایجاد عامل با خطا مواجه شد');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="container p-4">
      <h1 className="mb-3">ایجاد عامل جدید</h1>
      <form onSubmit={handleSubmit} className="card">
        <div className="card-body">
          <div className="form-group">
            <label className="form-label">نام</label>
            <input name="name" value={formData.name} onChange={handleChange} className="form-control" placeholder="نام عامل" />
          </div>
          <div className="form-group">
            <label className="form-label">نقش</label>
            <input name="role" value={formData.role} onChange={handleChange} className="form-control" placeholder="نقش عامل (کارگردان، بازیگر و ...)" />
          </div>
          <div className="form-group">
            <label className="form-label">بیوگرافی</label>
            <textarea name="bio" value={formData.bio} onChange={handleChange} className="form-control" placeholder="توضیحات کوتاه" />
          </div>
          <div className="form-group">
            <label className="form-label">تلفن</label>
            <input name="phone" value={formData.phone} onChange={handleChange} className="form-control" placeholder="شماره تماس" />
          </div>
          <div className="form-group">
            <label className="form-label">ایمیل</label>
            <input name="email" value={formData.email} onChange={handleChange} className="form-control" placeholder="example@mail.com" />
          </div>
        </div>
        <div className="card-footer" style={{ display: 'flex', gap: '10px' }}>
          <button type="submit" className="btn btn-success" disabled={loading}>{loading ? 'در حال ذخیره...' : 'ذخیره'}</button>
          <button type="button" className="btn btn-light" onClick={() => navigate('/actors')}>انصراف</button>
        </div>
      </form>
    </div>
  );
};

export default CreateActor;
