// Runtime switch between development and production CJS bundles of react-toastify
// to keep CRA4 compatibility in dev while using optimized bundle in prod.

const mod =
  process.env.NODE_ENV === 'production'
    ? require('react-toastify/dist/react-toastify.cjs.production.min.js')
    : require('react-toastify/dist/react-toastify.cjs.development.js');

export const toast = mod.toast;
// In some versions, ToastContainer may be exported as default; fallback accordingly.
export const ToastContainer = mod.ToastContainer || mod.default;
export type ToastOptions = import('react-toastify').ToastOptions;