import React, { useState } from 'react';
import { toast } from '../libs/toast';
import * as XLSX from 'xlsx';
import axios from 'axios';
import './BulkUpload.css';

const BulkUpload: React.FC = () => {
  const [file, setFile] = useState<File | null>(null);
  const [previewRows, setPreviewRows] = useState<any[]>([]);
  const [target, setTarget] = useState<'actors' | 'roles'>('actors');
  const [mapping, setMapping] = useState<any>({});
  const [loading, setLoading] = useState(false);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const f = e.target.files?.[0] || null;
    setFile(f);
    setPreviewRows([]);
    setMapping({});
    if (f) parseFile(f);
  };

  const parseFile = async (f: File) => {
    try {
      const buf = await f.arrayBuffer();
      const wb = XLSX.read(buf, { type: 'array' });
      const ws = wb.Sheets[wb.SheetNames[0]];
      const rows = XLSX.utils.sheet_to_json(ws, { defval: '' });
      setPreviewRows(rows.slice(0, 20));
      // Auto map headers by heuristic
      const headers = Object.keys(rows[0] || {});
      const lower = (s: string) => s.toLowerCase();
      const guess: any = {};
      if (target === 'actors') {
        guess.name = headers.find(h => /name|نام/.test(lower(h))) || headers[0];
        guess.role = headers.find(h => /role|نقش/.test(lower(h))) || headers[1] || headers[0];
        guess.phone = headers.find(h => /phone|تلفن|موبایل/.test(lower(h)));
        guess.email = headers.find(h => /email|ایمیل/.test(lower(h)));
        guess.bio = headers.find(h => /bio|زندگی/.test(lower(h)));
        guess.photo = headers.find(h => /photo|عکس/.test(lower(h)));
      } else {
        guess.code = headers.find(h => /code|کد/.test(lower(h))) || headers[0];
        guess.name = headers.find(h => /name|نام/.test(lower(h))) || headers[1] || headers[0];
      }
      setMapping(guess);
    } catch (e) {
      toast.error('خطا در خواندن فایل اکسل');
    }
  };

  const buildItems = (): any[] => {
    return previewRows.map((row: any) => {
      if (target === 'actors') {
        return {
          name: row[mapping.name] || '',
          role: row[mapping.role] || '',
          phone: mapping.phone ? row[mapping.phone] : undefined,
          email: mapping.email ? row[mapping.email] : undefined,
          bio: mapping.bio ? row[mapping.bio] : undefined,
          photo: mapping.photo ? row[mapping.photo] : undefined,
        };
      } else {
        return {
          code: row[mapping.code] || '',
          name: row[mapping.name] || '',
        };
      }
    }).filter(it => (target === 'actors' ? it.name && it.role : it.code && it.name));
  };

  const handleImport = async () => {
    const items = buildItems();
    if (items.length === 0) {
      toast.error('هیچ رکورد معتبری برای واردسازی یافت نشد');
      return;
    }
    setLoading(true);
    try {
      const token = localStorage.getItem('token');
      const url = target === 'actors' ? '/api/actors/bulk' : '/api/roles/bulk';
      const res = await axios.post(url, { items }, {
        headers: token ? { Authorization: `Bearer ${token}` } : undefined,
      });
      toast.success(`واردسازی ${res.data.count} رکورد با موفقیت انجام شد`);
    } catch (e) {
      toast.error('خطا در واردسازی داده‌ها');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bulk-container">
      <div className="bulk-header">
        <h1>واردسازی اکسل</h1>
      <p>فایل اکسل عوامل یا نقش‌ها را آپلود و ثبت دسته‌ای انجام دهید.</p>
      </div>

      <div className="bulk-controls">
        <div className="target-switch">
          <label>
            <input type="radio" checked={target==='actors'} onChange={()=>setTarget('actors')} /> عوامل
          </label>
          <label>
            <input type="radio" checked={target==='roles'} onChange={()=>setTarget('roles')} /> نقش‌ها
          </label>
        </div>
        <input type="file" accept=".xlsx,.xls" onChange={handleFileChange} />
      </div>

      {previewRows.length > 0 && (
        <div className="bulk-preview">
          <h3>پیش‌نمایش و نگاشت ستون‌ها</h3>
          <div className="mapping">
            {target === 'actors' ? (
              <>
                <FieldMap label="نام" value={mapping.name} onChange={(v)=>setMapping({...mapping,name:v})} headers={Object.keys(previewRows[0]||{})} />
                <FieldMap label="نقش" value={mapping.role} onChange={(v)=>setMapping({...mapping,role:v})} headers={Object.keys(previewRows[0]||{})} />
                <FieldMap label="تلفن" value={mapping.phone} onChange={(v)=>setMapping({...mapping,phone:v})} headers={Object.keys(previewRows[0]||{})} optional />
                <FieldMap label="ایمیل" value={mapping.email} onChange={(v)=>setMapping({...mapping,email:v})} headers={Object.keys(previewRows[0]||{})} optional />
                <FieldMap label="بیو" value={mapping.bio} onChange={(v)=>setMapping({...mapping,bio:v})} headers={Object.keys(previewRows[0]||{})} optional />
                <FieldMap label="عکس" value={mapping.photo} onChange={(v)=>setMapping({...mapping,photo:v})} headers={Object.keys(previewRows[0]||{})} optional />
              </>
            ) : (
              <>
                <FieldMap label="کد" value={mapping.code} onChange={(v)=>setMapping({...mapping,code:v})} headers={Object.keys(previewRows[0]||{})} />
                <FieldMap label="نام" value={mapping.name} onChange={(v)=>setMapping({...mapping,name:v})} headers={Object.keys(previewRows[0]||{})} />
              </>
            )}
          </div>

          <table className="preview-table">
            <thead>
              <tr>
                {Object.keys(previewRows[0]).map((h) => (<th key={h}>{h}</th>))}
              </tr>
            </thead>
            <tbody>
              {previewRows.map((row, idx) => (
                <tr key={idx}>
                  {Object.keys(previewRows[0]).map((h) => (<td key={h}>{row[h]}</td>))}
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      )}

      <div className="bulk-actions">
        <button className="import-btn" disabled={!file || loading} onClick={handleImport}>
          {loading ? 'در حال واردسازی...' : 'واردسازی'}
        </button>
      </div>
    </div>
  );
};

const FieldMap: React.FC<{ label: string; value?: string; headers: string[]; onChange: (v: string)=>void; optional?: boolean }>
  = ({ label, value, headers, onChange, optional }) => {
  return (
    <div className="field-map">
      <span className="label">{label}{optional ? ' (اختیاری)' : ''}</span>
      <select value={value || ''} onChange={(e)=>onChange(e.target.value)}>
        <option value="">— انتخاب ستون —</option>
        {headers.map((h) => (<option key={h} value={h}>{h}</option>))}
      </select>
    </div>
  );
};

export default BulkUpload;