import React, { useState } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { toast } from '../libs/toast';
import { FaUser, FaLock, FaSignInAlt } from 'react-icons/fa';
import { useAuth } from '../contexts/AuthContext';
import './Login.css';
import Logo from '../components/Logo';

const Login: React.FC = () => {
  const [username, setUsername] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const { login } = useAuth();
  const navigate = useNavigate();

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!username || !password) {
      toast.error('لطفاً نام کاربری و رمز عبور را وارد کنید');
      return;
    }

    setLoading(true);

    try {
      const success = await login(username, password);
      if (success) {
        toast.success('ورود موفقیت‌آمیز بود');
        navigate('/dashboard');
      } else {
        toast.error('نام کاربری یا رمز عبور اشتباه است');
      }
    } catch (error) {
      toast.error('خطا در ورود. لطفاً دوباره تلاش کنید');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="login-container">
      <div className="login-card">
        <div className="login-header">
          <div className="login-logo">
            <Logo src="/logo.png.jpg" height={144} width={144} alt="لوگو" />
            <h1>ورود به سامانه رسا</h1>
          </div>
          <p className="login-subtitle">به سامانه مدیریت یکپارچه و هوشمند صدور آفیش رسا خوش آمدید</p>
        </div>

        <form onSubmit={handleSubmit} className="login-form">
          <div className="form-group">
            <label htmlFor="username" className="form-label">
              <FaUser />
              نام کاربری
            </label>
            <input
              type="text"
              id="username"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              className="form-input"
              placeholder="نام کاربری خود را وارد کنید"
              disabled={loading}
            />
          </div>

          <div className="form-group">
            <label htmlFor="password" className="form-label">
              <FaLock />
              رمز عبور
            </label>
            <input
              type="password"
              id="password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="form-input"
              placeholder="رمز عبور خود را وارد کنید"
              disabled={loading}
            />
          </div>

          <button type="submit" className="login-btn" disabled={loading}>
            {loading ? (
              <span className="loading-spinner">در حال ورود...</span>
            ) : (
              <>
                <FaSignInAlt />
                ورود
              </>
            )}
          </button>
        </form>

        <div className="login-footer">
          <p>رمز عبور پیش‌فرض: admin123</p>
          <Link to="/">بازگشت به صفحه اصلی</Link>
        </div>
      </div>
    </div>
  );
};

export default Login;
