import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { toast } from '../libs/toast';
import {
  FaPlus, FaEye, FaEdit, FaTrash, FaSearch, FaCalendar,
  FaDownload, FaPrint, FaFilePdf
} from 'react-icons/fa';
import axios from 'axios';
import DateObject from 'react-date-object';
import persian from 'react-date-object/calendars/persian';
import gregorian from 'react-date-object/calendars/gregorian';
import DatePicker from 'react-multi-date-picker';
import { toPersianDigits } from '../utils/locale';
import announcementGenerator from '../utils/announcementGenerator';
import './Announcements.css';

const Announcements: React.FC = () => {
  const [announcements, setAnnouncements] = useState([]);
  const [filteredAnnouncements, setFilteredAnnouncements] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [dateFilter, setDateFilter] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('');
  const [presetName, setPresetName] = useState('');
  const [presets, setPresets] = useState<Array<{ name: string; search: string; date: string; status: string }>>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    fetchAnnouncements();
    const saved = localStorage.getItem('ann_filter_presets');
    if (saved) {
      try { setPresets(JSON.parse(saved)); } catch { }
    }
  }, []);

  useEffect(() => {
    filterAnnouncements();
  }, [announcements, searchTerm, dateFilter]);

  const fetchAnnouncements = async () => {
    try {
      const response = await axios.get('/api/announcements');
      setAnnouncements(response.data);
    } catch (error) {
      toast.error('خطا در دریافت آفیش‌ها');
    } finally {
      setLoading(false);
    }
  };

  const filterAnnouncements = () => {
    let filtered = announcements;

    if (searchTerm) {
      filtered = filtered.filter((announcement: any) =>
        announcement.title.toLowerCase().includes(searchTerm.toLowerCase()) ||
        (announcement.program_title || announcement.program?.name || '')
          .toLowerCase().includes(searchTerm.toLowerCase()) ||
        announcement.actors?.some((actor: any) =>
          actor.name.toLowerCase().includes(searchTerm.toLowerCase())
        )
      );
    }

    if (dateFilter) {
      filtered = filtered.filter((announcement: any) =>
        announcement.date === dateFilter
      );
    }

    if (statusFilter) {
      filtered = filtered.filter((announcement: any) =>
        (announcement.status || '') === statusFilter
      );
    }

    setFilteredAnnouncements(filtered);
  };

  const handleDelete = async (id: string) => {
    if (window.confirm('آیا از حذف این آفیش مطمئن هستید؟')) {
      try {
        // Optimistic UI
        const prev = announcements;
        setAnnouncements((list: any) => list.filter((a: any) => a.id !== id));
        setFilteredAnnouncements((list: any) => list.filter((a: any) => a.id !== id));
        const token = localStorage.getItem('token');
        await axios.delete(`/api/announcements/${id}`, {
          headers: token ? { Authorization: `Bearer ${token}` } : undefined,
        });
        toast.success('آفیش با موفقیت حذف شد');
      } catch (error) {
        toast.error('خطا در حذف آفیش؛ بازگشت به حالت قبل');
        fetchAnnouncements();
      }
    }
  };

  const savePreset = () => {
    if (!presetName.trim()) { toast.error('نام پرِست را وارد کنید'); return; }
    const next = presets.filter(p => p.name !== presetName).concat([{ name: presetName, search: searchTerm, date: dateFilter, status: statusFilter }]);
    setPresets(next);
    localStorage.setItem('ann_filter_presets', JSON.stringify(next));
    toast.success('پرِست ذخیره شد');
  };

  const applyPreset = (p: { name: string; search: string; date: string; status: string }) => {
    setSearchTerm(p.search);
    setDateFilter(p.date);
    setStatusFilter(p.status);
  };

  const handlePrint = async (announcement: any) => {
    try {
      await announcementGenerator.generatePDF(announcement);
      toast.success('فایل PDF با موفقیت ایجاد شد');
    } catch (error) {
      toast.error('خطا در ایجاد فایل PDF');
    }
  };

  const formatDate = (dateString: string) => {
    try {
      const obj = new DateObject({ date: new Date(dateString) });
      return obj.convert(persian).format('YYYY/MM/DD');
    } catch {
      return dateString;
    }
  };

  const formatTime = (timeString: string) => {
    return toPersianDigits(timeString || '');
  };

  if (loading) {
    return (
      <div className="announcements-container">
        <div className="page-header">
          <h1>مدیریت آفیش‌ها</h1>
          <button className="add-btn" disabled>
            <FaPlus />
            آفیش جدید
          </button>
        </div>
        <div className="filters-section skeleton-block" />
        <div className="announcements-grid">
          {Array.from({ length: 6 }).map((_, i) => (
            <div key={i} className="announcement-card skeleton">
              <div className="skeleton-title" />
              <div className="skeleton-line" />
              <div className="skeleton-line" />
              <div className="skeleton-line short" />
              <div className="card-footer">
                <div className="skeleton-badge" />
                <div className="skeleton-small" />
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="announcements-container">
      <div className="page-header">
        <h1>مدیریت آفیش‌ها</h1>
        <Link to="/announcements/new" className="add-btn">
          <FaPlus />
          آفیش جدید
        </Link>
      </div>

      <div className="filters-section">
        <div className="search-box">
          <FaSearch />
          <input
            type="text"
            placeholder="جستجو در عنوان، برنامه یا عوامل..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="search-input"
          />
        </div>
        <div className="date-filter">
          <FaCalendar />
          <DatePicker
            calendar={persian}
            inputClass="date-input"
            value={dateFilter ? new DateObject({ date: new Date(dateFilter) }).convert(persian) : null}
            onChange={(val: any) => {
              if (!val) { setDateFilter(''); return; }
              try {
                const obj = val instanceof DateObject ? val : new DateObject(val);
                const g = obj.convert(gregorian).format('YYYY-MM-DD');
                setDateFilter(g);
              } catch {
                toast.error('خطا در تنظیم فیلتر تاریخ');
              }
            }}
            format="YYYY/MM/DD"
            placeholder="فیلتر تاریخ (شمسی)"
          />
          {dateFilter && (
            <button
              onClick={() => setDateFilter('')}
              className="clear-date-btn"
            >
              حذف فیلتر
            </button>
          )}
        </div>
        <div className="status-filter">
          <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} className="status-select">
            <option value="">همه وضعیت‌ها</option>
            <option value="published">منتشر شده</option>
            <option value="draft">پیش‌نویس</option>
          </select>
        </div>
        <div className="preset-controls">
          <input type="text" value={presetName} onChange={(e) => setPresetName(e.target.value)} placeholder="نام پرِست" className="preset-input" />
          <button className="btn btn-light" onClick={savePreset}>ذخیره پرِست</button>
          {presets.length > 0 && (
            <select onChange={(e) => { const p = presets.find(pp => pp.name === e.target.value); if (p) applyPreset(p); }} className="preset-select">
              <option value="">اعمال پرِست...</option>
              {presets.map(p => (<option key={p.name} value={p.name}>{p.name}</option>))}
            </select>
          )}
        </div>
      </div>

      <div className="announcements-grid">
        {filteredAnnouncements.length === 0 ? (
          <div className="empty-state">
            <FaFilePdf />
            <p>هیچ آفیشی یافت نشد</p>
            <Link to="/announcements/new" className="create-first-btn">
              ایجاد اولین آفیش
            </Link>
          </div>
        ) : (
          filteredAnnouncements.map((announcement: any) => (
            <div key={announcement.id} className="announcement-card">
              <div className="card-header">
                <h3>{announcement.title}</h3>
                <div className="card-actions">
                  <button
                    onClick={() => handlePrint(announcement)}
                    className="action-btn print"
                    title="چاپ/دانلود PDF"
                  >
                    <FaDownload />
                  </button>
                  <Link
                    to={`/announcements/${announcement.id}`}
                    className="action-btn view"
                    title="مشاهده"
                  >
                    <FaEye />
                  </Link>
                  <Link
                    to={`/announcements/${announcement.id}/edit`}
                    className="action-btn edit"
                    title="ویرایش"
                  >
                    <FaEdit />
                  </Link>
                  <button
                    onClick={() => handleDelete(announcement.id)}
                    className="action-btn delete"
                    title="حذف"
                  >
                    <FaTrash />
                  </button>
                </div>
              </div>

              <div className="card-content">
                <div className="info-row">
                  <span className="label">برنامه:</span>
                  <span className="value">{announcement.program_title || 'بدون برنامه'}</span>
                </div>
                <div className="info-row">
                  <span className="label">تاریخ:</span>
                  <span className="value">{formatDate(announcement.date)}</span>
                </div>
                <div className="info-row">
                  <span className="label">زمان:</span>
                  <span className="value">{formatTime(announcement.time)}</span>
                </div>
                <div className="info-row">
                  <span className="label">مکان:</span>
                  <span className="value">{announcement.venue || 'ثبت نشده'}</span>
                </div>
                {/* نمایش عوامل در فهرست نیازمند دریافت جداگانه است؛ فعلاً پنهان می‌ماند */}
                {announcement.description && (
                  <div className="info-row">
                    <span className="label">توضیحات:</span>
                    <span className="value description">{announcement.description}</span>
                  </div>
                )}
              </div>

              <div className="card-footer">
                <div className="status-badge">
                  {announcement.status === 'published' ? 'منتشر شده' : 'پیش‌نویس'}
                </div>
                <div className="created-info">
                  ایجاد شده در: {formatDate(announcement.created_at?.split('T')[0])}
                </div>
              </div>
            </div>
          ))
        )}
      </div>
    </div>
  );
};

export default Announcements;
